def apply_full_fill(grid):
    """
    Fill gaps in BOTH directions:
    1. Each row: fill gaps between consecutive frame cells horizontally
    2. Each col: fill gaps between consecutive frame cells vertically
    3. Frame color = 1, fill color = 2
    """
    h, w = len(grid), len(grid[0]) if grid else 0

    # Collect all frame positions
    frame_positions = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                frame_positions.add((r, c))

    if not frame_positions:
        return grid

    # Fill horizontal gaps first
    for r in range(h):
        frame_in_row = [c for c in range(w) if r < len(grid) and grid[r][c] == 1]
        for i in range(len(frame_in_row) - 1):
            for c in range(frame_in_row[i] + 1, frame_in_row[i+1]):
                grid[r][c] = 2

    # Fill vertical gaps
    for c in range(w):
        frame_in_col = [r for r in range(h) if grid[r][c] == 1]
        for i in range(len(frame_in_col) - 1):
            for r in range(frame_in_col[i] + 1, frame_in_col[i+1]):
                if grid and r < len(grid) and grid[r][c] == 3:  # Only fill background
                    grid[r][c] = 2

    return grid

